mat4 viewMatrix;
vec3 cameraPosition;
vec4 cameraQuaternion;
vec2 resolution;
float time;
float timeScale;
};
out vec4 FragColor;




uniform sampler2D blurTexture1;
uniform sampler2D blurTexture2;
uniform sampler2D blurTexture3;

uniform float bloomStrength;
uniform float bloomRadius;
uniform vec3 bloomTintColor;


in vec2 vUv;



float lerpBloomFactor(const in float factor) {
    float mirrorFactor = 1.2 - factor;
    return mix(factor, mirrorFactor, bloomRadius);
}

void main() {
    FragColor = bloomStrength * (lerpBloomFactor(1.0000) * vec4(bloomTintColor, 1.0) * texture(blurTexture1, vUv) + lerpBloomFactor(0.8000) * vec4(bloomTintColor, 1.0) * texture(blurTexture2, vUv) + lerpBloomFactor(0.6000) * vec4(bloomTintColor, 1.0) * texture(blurTexture3, vUv) );
}

