uniform float uSoftenEdge;
uniform vec2 uResolution;


in vec2 vUv;


void main() {

    vec2 uv = vUv;

    float dx = 1. / uResolution.x;

    float u0 = uv.x - dx;
    float u1 = uv.x;
    float u2 = uv.x + dx;

    // sample horizontally
    vec3 c0 = texture(tScene, vec2(u0, uv.y)).rgb / 4.;
    vec3 c1 = texture(tScene, vec2(u1, uv.y)).rgb / 2.;
    vec3 c2 = texture(tScene, vec2(u2, uv.y)).rgb / 4.;

    vec3 c3 = texture(tHigh, uv).rgb;

    vec3 cStretch = c0 + c1 + c2;

    // sample vertically
    vec3 c4 = texture(tScene, vec2(uv.x, uv.y - (dx * 0.75))).rgb / 4.;
    vec3 c5 = texture(tScene, vec2(uv.x, uv.y + (dx * 0.75))).rgb / 4.;

    cStretch += (c4 + c5) * uSoftenEdge;

    vec4 col = vec4(cStretch, 1.);

    FragColor = col;

}

